\definecolor{accent}{HTML}{F59E0B}      % amber
\definecolor{vermilion}{HTML}{EF4444}   % vermilion
\definecolor{deepred}{HTML}{B91C1C}     % deep red
\definecolor{teal}{HTML}{14B8A6}        % teal
\definecolor{coolblue}{HTML}{0EA5E9}    % cool blue
\definecolor{bgposter}{HTML}{0B1120}    % poster background
\definecolor{cardbg}{HTML}{111827}      % card background
\definecolor{cardbg2}{HTML}{1E293B}     % card background alt
\definecolor{cardbg3}{HTML}{172554}     % card background blue tint
\definecolor{cardtitlebg}{HTML}{1E293B} % card title bar
\definecolor{textlight}{HTML}{F8FAFC}   % primary text
\definecolor{textgray}{HTML}{94A3B8}    % secondary text
\definecolor{stathighlight}{HTML}{1E293B}
\definecolor{accentbg}{HTML}{451A03}    % amber tint bg
\definecolor{redbg}{HTML}{450A0A}       % red tint bg
\definecolor{bluebg}{HTML}{0C1E3A}      % blue tint bg

\pagecolor{bgposter}
\color{textlight}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{accent}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{coolblue}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{26}{32}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles ──
\tcbset{
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={6pt}{0pt}{accent},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardtitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.22},
  },
