    borderline west={6pt}{0pt}{vermilion},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{vermilion},
    coltitle=vermilion, colbacktitle=cardtitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={vermilion!50},
    valign=top, drop shadow={opacity=0.22},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={6pt}{0pt}{coolblue},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{coolblue},
    coltitle=coolblue, colbacktitle=cardtitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={coolblue!50},
    valign=top, drop shadow={opacity=0.22},
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={6pt}{0pt}{teal},
    left=18pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{teal},
    coltitle=teal, colbacktitle=cardtitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={teal!50},
    valign=top, drop shadow={opacity=0.22},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=deepred!15!bgposter,
    borderline west={8pt}{0pt}{deepred},
