  drop shadow={opacity=0.4}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{72}{88}\selectfont\bfseries Climate Change 2023}\\[10pt]
  {\fontsize{48}{58}\selectfont Key Findings from the IPCC Sixth Assessment Synthesis Report}\\[14pt]
  {\fontsize{32}{40}\selectfont\color{textgray} Intergovernmental Panel on Climate Change (IPCC) | 2023}
}

% ═══════════════════════════════════════════════════════════════════════════
% STATS BANNER (7 metrics across 3 columns, row4 to row6)
% ═══════════════════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=secondary, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=8pt, bottom=8pt,
