]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.13\linewidth}\centering
    \fcolorbox{accent!50}{bgposter}{\parbox{0.92\linewidth}{%
      \centering\vspace{8pt}%
