cd /app/poster && python3 -c "
import fitz
doc = fitz.open('main.pdf')
page = doc[0]
# Let's examine the PDF more carefully
# Maybe the rectangle is being drawn but then covered by a white rectangle
content = page.read_contents().decode('latin-1')
lines = content.split('\n')
# Find ALL 're f' commands and their preceding colors
for i, line in enumerate(lines):
    if 're f' in line:
        # Get color from preceding lines
        color = None
        for j in range(i-1, max(0, i-15), -1):
            if 'rg' in lines[j] or 'RG' in lines[j]:
                color = lines[j]
                break
        # Get rect size
        rect_line = None
        for j in range(i-1, max(0, i-5), -1):
            if 'cm' not in lines[j] and len(lines[j].strip().split()) >= 2:
                try:
                    parts = lines[j].strip().split()
                    if len(parts) >= 2:
                        rect_line = parts[-4:]
                        break
                except:
                    pass
        print(f'Line {i}: rect={rect_line}, color={color.strip() if color else None}')
"

